import renderRef from "@context/render_context";
/**
 * Base class for all shapes
 * @class
 */
class PrimitiveAbstract {
    /**
     * Transformation matrices
     */
    constructor() { }
    /**
     * Internal method to compile shader programs
     *
     */
    static _compileShaderProgram(vertexShaderCode, fragmentShaderCode) {
        /* Get WebglContext ref */
        const gl = renderRef.elementRef;
        if (!gl) {
            console.trace();
            throw new Error("No webgl rendering context");
        }
        /*COMPILE SHADERS */
        const vertexShader = gl.createShader(gl.VERTEX_SHADER);
        if (!vertexShader) {
            console.trace();
            throw new Error("Vertex shader could not be created");
        }
        gl.shaderSource(vertexShader, vertexShaderCode);
        gl.compileShader(vertexShader);
        const vCompileSuccess = gl.getShaderParameter(vertexShader, gl.COMPILE_STATUS);
        if (!vCompileSuccess) {
            console.log(`Vertex Shader failed to compile: ${gl.getShaderInfoLog(vertexShader)}`);
            gl.deleteShader(vertexShader);
            throw new Error(`Vertex Shader failed to compile: ${gl.getShaderInfoLog(vertexShader)}`);
        }
        /* Compile fragment shader */
        const fragmentShader = gl.createShader(gl.FRAGMENT_SHADER);
        if (!fragmentShader) {
            console.trace();
            throw new Error("Fragment shader could not be created");
        }
        gl.shaderSource(fragmentShader, fragmentShaderCode);
        gl.compileShader(fragmentShader);
        const fCompileSuccess = gl.getShaderParameter(fragmentShader, gl.COMPILE_STATUS);
        if (!fCompileSuccess) {
            console.log(gl.getShaderInfoLog(fragmentShader));
            gl.deleteShader(vertexShader);
            gl.deleteShader(fragmentShader);
            throw new Error(`Fragment Shader failed to compile: ${gl.getShaderInfoLog(fragmentShader)}`);
        }
        /* CREATE SHADER PROGRAM */
        const program = gl.createProgram();
        gl.attachShader(program, vertexShader);
        gl.attachShader(program, fragmentShader);
        gl.linkProgram(program);
        const success = gl.getProgramParameter(program, gl.LINK_STATUS);
        if (!success) {
            gl.deleteProgram(program);
            throw new Error("Shader program failed to link.");
        }
        return program;
    }
    /**
     * Internal method to create VAO for positional attributes
     */
    static _createPositionVAO(program, positionBuffer, positionIndexBuffer) {
        // Create and bind VAO
        const vao = renderRef.elementRef?.createVertexArray();
        if (!vao) {
            console.trace();
            throw new Error("VAO failed to be created");
        }
        renderRef.elementRef?.bindVertexArray(vao);
        // Get attribute location, enable, and define method to extract data from buffer
        const a_pos_loc = renderRef.elementRef?.getAttribLocation(program, "a_position");
        if (a_pos_loc === -1) {
            console.trace();
            throw new Error("Position Attribute could not be located");
        }
        renderRef.elementRef?.enableVertexAttribArray(a_pos_loc);
        /* Position buffer contains default buffer details */
        renderRef.elementRef?.bindBuffer(renderRef.elementRef.ARRAY_BUFFER, positionBuffer);
        renderRef.elementRef?.vertexAttribPointer(a_pos_loc, // Attribute location
        3, // Components per vertex (x, y, z)
        renderRef.elementRef.FLOAT, false, 0, 0);
        /* INDICES */
        if (positionIndexBuffer) {
            renderRef.elementRef.bindBuffer(renderRef.elementRef?.ELEMENT_ARRAY_BUFFER, positionIndexBuffer);
        }
        /* Clean up */
        renderRef.elementRef?.bindVertexArray(null);
        renderRef.elementRef.bindBuffer(renderRef.elementRef?.ELEMENT_ARRAY_BUFFER, null);
        return vao;
    }
    static _createBoundingVAO(program, positionBuffer, positionIndexBuffer) {
        // Create and bind VAO
        const vao = renderRef.elementRef?.createVertexArray();
        if (!vao) {
            console.trace();
            throw new Error("VAO failed to be created");
        }
        renderRef.elementRef?.bindVertexArray(vao);
        // Get attribute location, enable, and define method to extract data from buffer
        const a_pos_loc = renderRef.elementRef?.getAttribLocation(program, "a_position");
        if (a_pos_loc === -1) {
            console.trace();
            throw new Error("Position Attribute could not be located");
        }
        renderRef.elementRef?.enableVertexAttribArray(a_pos_loc);
        /* Position buffer contains default buffer details */
        renderRef.elementRef?.bindBuffer(renderRef.elementRef.ARRAY_BUFFER, positionBuffer);
        renderRef.elementRef?.vertexAttribPointer(a_pos_loc, // Attribute location
        3, // Components per vertex (x, y, z)
        renderRef.elementRef.FLOAT, false, 0, 0);
        /* INDICES */
        if (positionIndexBuffer) {
            renderRef.elementRef.bindBuffer(renderRef.elementRef?.ELEMENT_ARRAY_BUFFER, positionIndexBuffer);
        }
        /* Clean up */
        renderRef.elementRef?.bindVertexArray(null);
        renderRef.elementRef.bindBuffer(renderRef.elementRef?.ELEMENT_ARRAY_BUFFER, null);
        return vao;
    }
    /**
     * Bind buffer data
     */
    static createStaticVertexBuffer(data) {
        const buffer = renderRef.elementRef?.createBuffer();
        if (!buffer) {
            console.trace();
            throw new Error("Static vertex buffer failed to be created");
        }
        try {
            renderRef.elementRef?.bindBuffer(renderRef.elementRef.ARRAY_BUFFER, buffer);
            renderRef.elementRef?.bufferData(renderRef.elementRef.ARRAY_BUFFER, data, renderRef.elementRef.STATIC_DRAW);
            renderRef.elementRef?.bindBuffer(renderRef.elementRef.ARRAY_BUFFER, null);
        }
        catch (e) {
            console.trace();
            throw new Error(e);
        }
        return buffer;
    }
    static createElementArrayBuffer(data) {
        const buffer = renderRef.elementRef?.createBuffer();
        if (!buffer) {
            console.trace();
            throw new Error("Element Array buffer failed to be created");
        }
        try {
            renderRef.elementRef?.bindBuffer(renderRef.elementRef.ELEMENT_ARRAY_BUFFER, buffer);
            renderRef.elementRef?.bufferData(renderRef.elementRef.ELEMENT_ARRAY_BUFFER, data, renderRef.elementRef.STATIC_DRAW);
            renderRef.elementRef?.bindBuffer(renderRef.elementRef.ELEMENT_ARRAY_BUFFER, null);
        }
        catch (e) {
            console.trace();
            throw new Error(e);
        }
        return buffer;
    }
    /* STANDARD METHODS TO PROGRAMMATICALLY TRANSFORM AN OBJECT WITHOUT USER INTERACTION */
    automaticRotation() { }
}
export default PrimitiveAbstract;
