import debugRef from "@context/debug";
import { mat4, vec3 } from "gl-matrix";
/**
 * Defines Player object and other params, e.g. camera position, textures, movement behaviour etc.
 * @class
 */
class PlayerObject {
    playerObject = null;
    cameraRotation = null;
    cameraMatrix = null;
    /**
     * Camera offset from player object
     */
    cameraOffset = null;
    frontVector = null;
    rightVector = null;
    upVector = null;
    /**
     * Y axis is defined by the position of the player object
     */
    globalYaw = null;
    /**
     * x Axis is defined by the position of the camera
     */
    localPitch = null;
    /**
     * Physics vectors
     */
    velocity = null; //Resultant velocity
    acceleration = null; // Resultant acceleration
    movementAcceleration = null; // Force applied from movement
    // Friction applied when moving through space
    spaceFriction = 0.005;
    /**
     * PHYSICS SCALARS
     */
    mass = 0;
    defaultMovementForceScalar = 2;
    defaultRotationSpeed = 0.05;
    /**
     * Input States
     */
    aH = 0; //HOrizontal movement
    aV = 0; // Vertical Camera movement
    dp = 0; // Forward and backwards movement
    ds = 0; // Strafing
    /**
     * Initialises player object model,  which can be a any PrimitiveBase shape
     */
    constructor(playerObject, cameraOffset, mass) {
        // Initialise player details
        this.playerObject = playerObject;
        this.mass = mass;
        this.acceleration = vec3.create();
        // Initialise camera
        this.cameraMatrix = mat4.create();
        this.cameraRotation = mat4.create();
        this.upVector = vec3.fromValues(0, 1, 0);
        this.cameraOffset = vec3.fromValues(cameraOffset[0], cameraOffset[1], cameraOffset[2]);
        this.globalYaw = 0;
        this.localPitch = 0;
        this.velocity = vec3.create();
        this.movementAcceleration = vec3.create();
    }
    /**
     * Update player object and camera
     * @param inputState
     */
    updatePosition(isColliding) {
        if (isColliding)
            vec3.scale(this.velocity, this.velocity, 0.95);
        // APPLY AMBIENT FORCES
        vec3.scale(this.velocity, this.velocity, (1 - this.spaceFriction));
        /**
         * Resolve forces
         */
        // Apply player movement forces
        vec3.add(this.acceleration, this.ambientForce, this.movementAcceleration);
        // Add acceleration force to velocity
        vec3.add(this.velocity, this.velocity, this.acceleration);
        debugRef.elementRef.innerHTML = `
      x: ${this.velocity[0].toFixed(2)}
      y: ${this.velocity[1].toFixed(2)}
      z: ${this.velocity[2].toFixed(2)}
    `;
        this.playerObject?.updatePosition(this.velocity, this.aH);
        // Apply pitch (rotation around the X-axis) to the camera - up/down
        mat4.rotateX(this.cameraRotation, this.cameraRotation, this.aV);
        // FINAL TARGET VECTOR
        const finalTarget = vec3.create();
        vec3.add(finalTarget, finalTarget, this.playerObject.position);
        // CREATE CAMERA POSITION VECTOR
        const cameraPosition = vec3.create();
        vec3.add(cameraPosition, this.playerObject.position, this.cameraOffset);
        const forward = vec3.fromValues(0, 1, 0);
        vec3.transformMat4(forward, this.cameraOffset, this.cameraRotation);
        vec3.add(cameraPosition, this.playerObject.position, forward);
        vec3.rotateY(cameraPosition, cameraPosition, this.playerObject.position, this.globalYaw);
        mat4.lookAt(this.cameraMatrix, cameraPosition, finalTarget, this.upVector);
    }
    rePosition(v) {
        this.playerObject?.updatePosition(v, 0);
    }
    updateMovement(inputState, ambientForce = null) {
        this.aH = 0;
        this.aV = 0;
        if (inputState.isWPressed)
            this.aV = this.defaultRotationSpeed;
        if (inputState.isSPressed)
            this.aV = -this.defaultRotationSpeed;
        if (inputState.isDPressed)
            this.aH = -this.defaultRotationSpeed;
        if (inputState.isAPressed)
            this.aH = this.defaultRotationSpeed;
        this.dp = 0;
        this.ds = 0;
        if (inputState.isUpArrowPressed)
            this.dp = -this.defaultMovementForceScalar;
        if (inputState.isDownArrowPressed)
            this.dp = this.defaultMovementForceScalar;
        if (inputState.isRightArrowPressed)
            this.ds = this.defaultMovementForceScalar;
        if (inputState.isLeftArrowPressed)
            this.ds = -this.defaultMovementForceScalar;
        this.dp /= this.mass;
        this.ds /= this.mass;
        this.globalYaw += this.aH;
        this.localPitch += this.aV;
        if (this.localPitch > 45 * (Math.PI / 180)) {
            this.localPitch = 45 * (Math.PI / 180);
            this.aV = 0;
        }
        else if (this.localPitch < -45 * (Math.PI / 180)) {
            this.localPitch = -45 * (Math.PI / 180);
            this.aV = 0;
        }
        /**
         * APPLY FORCES ONTO PLAER ACCELERATION
         */
        // TRANSLATE PLAYER  OBJECT
        let dx = this.dp * Math.sin(this.globalYaw) + this.ds * Math.cos(-this.globalYaw);
        let dz = this.dp * Math.cos(this.globalYaw) + this.ds * Math.sin(-this.globalYaw);
        let dy = this.dp * Math.sin(-this.localPitch);
        // Create movement acceleration vector
        this.movementAcceleration = vec3.fromValues(dx, dy, dz);
        // Assign ambient force vector (e.g. gravity)
        this.ambientForce = ambientForce;
    }
}
export default PlayerObject;
