import PrimitiveAbstract from "@models/primitiveAbstract";
import { quat, mat4, vec3, glMatrix } from "gl-matrix";
import renderRef from "@context/render_context";
/**
 * Sphere primitive
 * @class
 */
class SpherePrimitive extends PrimitiveAbstract {
    _vertexArray = new Float32Array([]);
    _vertexIndices = new Uint16Array([]);
    /**
     * Default vertex shader code here. User can provide custom shader code
     */
    _vertexShader = `#version 300 es
  precision mediump float;
  
  in vec3 a_position;
  uniform mat4 matWorld;
  uniform mat4 matViewProj;
  out vec4 fragmentColor;
  void main() {
    fragmentColor =  vec4(a_position,1.0);
    gl_Position = matViewProj * matWorld * vec4(a_position, 1.0);
  }`;
    _boundingVertexShader = `#version 300 es
  precision highp float;
  
  in vec3 a_position;
  out vec3 fragmentColor;

  uniform mat4 matWorld;
  uniform mat4 matViewProj;

  void main(){
    fragmentColor = vec3(0.0, 0.2, 1.0);
    gl_Position = matViewProj  * vec4(a_position, 1.0);
  }`;
    _fragmentShader = `#version 300 es
  precision mediump float;

  in vec4 fragmentColor;
  out vec4 fragColor;

  // Plot a line on Y using a value between 0.0-1.0
  void main(){
    fragColor = fragmentColor;
  }
  
  `;
    _boundingFragmentShader = `#version 300 es
  precision highp float;

  in vec3 fragmentColor;
  out vec4 outputColor;

  void main(){
    outputColor = vec4(fragmentColor, 1.0);
  }
  
  `;
    _shaderProgram = null;
    _boundingShaderProgram = null;
    /**
     * Object VAO References
     */
    _positionVAO = null;
    _boundingVAO = null;
    /**
     * Buffers
     */
    _positionBuffer = null;
    _positionIndexBuffer = null;
    _boundingBuffer = null;
    _boundingVertices = [];
    _boundingIndices = [];
    /**
     * BOUNDING
     */
    enableBoundingBox = false;
    _radius = 1;
    /**
     * Placement
     */
    _xPos = 0;
    _yPos = 0;
    _zPos = 0;
    _rotationQuat = null;
    position = null;
    boundingBox = null;
    boundingBoxType = "sphere";
    constructor(vertexShaderCode, fragmentShaderCode, xPos = 0, yPos = 0, zPos = 0, radius = 0, rotationX = 0, rotationY = 0, rotationZ = 0, enableBoundingBox = false) {
        super();
        this._radius = radius;
        // Determine vertices
        this._createSphere();
        /* SHAPE SIZING */
        const rotationQuat = quat.create();
        quat.rotateX(rotationQuat, rotationQuat, glMatrix.toRadian(rotationX));
        quat.rotateY(rotationQuat, rotationQuat, glMatrix.toRadian(rotationY));
        quat.rotateZ(rotationQuat, rotationQuat, glMatrix.toRadian(rotationZ));
        this._rotationQuat = rotationQuat;
        this._xPos = xPos;
        this._yPos = yPos;
        this._zPos = zPos;
        this.position = vec3.fromValues(xPos, yPos, zPos);
        // Attempt to compile shader program
        const program = PrimitiveAbstract._compileShaderProgram(vertexShaderCode ?? this._vertexShader, fragmentShaderCode ?? this._fragmentShader);
        this._shaderProgram = program;
        // Create position buffer
        const positionBuffer = PrimitiveAbstract.createStaticVertexBuffer(this._vertexArray);
        this._positionBuffer = positionBuffer;
        // // Create position index buffer
        const positionIndexBuffer = PrimitiveAbstract.createElementArrayBuffer(this._vertexIndices);
        this._positionIndexBuffer = positionIndexBuffer;
        // Create position vao
        const vao = PrimitiveAbstract._createPositionVAO(this._shaderProgram, positionBuffer, positionIndexBuffer);
        this._positionVAO = vao;
        if (this.boundingBox && enableBoundingBox)
            return;
        this._generateBoundingBox();
        this.enableBoundingBox = enableBoundingBox;
        // Attempt to compile shader program
        const boundingProgram = PrimitiveAbstract._compileShaderProgram(vertexShaderCode ?? this._boundingVertexShader, fragmentShaderCode ?? this._boundingFragmentShader);
        this._boundingShaderProgram = boundingProgram;
        // Create position buffer
        const bbpositionBuffer = PrimitiveAbstract.createStaticVertexBuffer(this._boundingVertices);
        this._boundingBuffer = bbpositionBuffer;
        // Create position index buffer
        const boundingPositionIndexBuffer = PrimitiveAbstract.createElementArrayBuffer(this._boundingIndices);
        this._boundingPositionIndexBuffer = boundingPositionIndexBuffer;
        // Create position vao
        const bbvao = PrimitiveAbstract._createBoundingVAO(boundingProgram, bbpositionBuffer, boundingPositionIndexBuffer);
        this._boundingVAO = bbvao;
    }
    _createSphere() {
        const DENSITY = 20;
        let i, ai, si, ci;
        let j, aj, sj, cj;
        let p1, p2;
        const vertices = [], indices = [];
        for (j = 0; j <= DENSITY; j++) {
            aj = (j * Math.PI) / DENSITY;
            sj = Math.sin(aj);
            cj = Math.cos(aj);
            for (i = 0; i <= DENSITY; i++) {
                ai = (i * 2 * Math.PI) / DENSITY;
                si = Math.sin(ai);
                ci = Math.cos(ai);
                vertices.push(si * sj); //x
                vertices.push(cj); //y
                vertices.push(ci * sj); //z
            }
        }
        this._vertexArray = new Float32Array(vertices);
        for (j = 0; j < DENSITY; j++) {
            for (i = 0; i < DENSITY; i++) {
                p1 = j * (DENSITY + 1) + i;
                p2 = p1 + (DENSITY + 1);
                indices.push(p1);
                indices.push(p2);
                indices.push(p1 + 1);
                indices.push(p1 + 1);
                indices.push(p2);
                indices.push(p2 + 1);
            }
        }
        this._vertexIndices = new Uint16Array(indices);
    }
    updatePosition(translate, rotationY) {
        vec3.add(this.position, this.position, translate);
        quat.rotateY(this._rotationQuat, this._rotationQuat, glMatrix.toRadian(rotationY));
        if ((translate[0] || translate[1] || translate[2])) {
            this._updateBoundingBox();
        }
    }
    draw(projectionMatrix, cameraMatrix) {
        /* Use program */
        renderRef.elementRef?.useProgram(this._shaderProgram);
        /* bind and enable VAO standard VAOs */
        renderRef.elementRef?.bindVertexArray(this._positionVAO);
        /* Uniforms */
        const matWorldUniform = renderRef.elementRef?.getUniformLocation(this._shaderProgram, "matWorld");
        const matViewProjUniform = renderRef.elementRef?.getUniformLocation(this._shaderProgram, "matViewProj");
        /* Model tranform */
        const matWorld = mat4.create();
        const rotationMatrix = mat4.create();
        quat.normalize(this._rotationQuat, this._rotationQuat);
        mat4.fromQuat(rotationMatrix, this._rotationQuat);
        // Apply translation to the world matrix
        mat4.translate(matWorld, matWorld, this.position);
        mat4.scale(matWorld, matWorld, vec3.fromValues(this._radius, this._radius, this._radius));
        mat4.multiply(matWorld, matWorld, rotationMatrix);
        // Camera and project matrix
        const matViewProj = mat4.create();
        mat4.multiply(matViewProj, projectionMatrix, cameraMatrix);
        renderRef.elementRef?.uniformMatrix4fv(matWorldUniform, false, matWorld);
        renderRef.elementRef?.uniformMatrix4fv(matViewProjUniform, false, matViewProj);
        /* Issue draw call */
        try {
            renderRef.elementRef?.drawElements(renderRef.elementRef.TRIANGLES, this._vertexIndices.length, renderRef.elementRef.UNSIGNED_SHORT, 0);
        }
        catch (e) {
            throw new Error(e);
        }
        if (!this.enableBoundingBox)
            return;
        renderRef.elementRef?.bindVertexArray(null);
        /* Use program */
        renderRef.elementRef?.useProgram(this._boundingShaderProgram);
        /* bind and enable VAO standard VAOs */
        renderRef.elementRef?.bindVertexArray(this._boundingVAO);
        const boundingMatWorldUniform = renderRef.elementRef?.getUniformLocation(this._boundingShaderProgram, "matWorld");
        const boundingMatViewProjUniform = renderRef.elementRef?.getUniformLocation(this._boundingShaderProgram, "matViewProj");
        renderRef.elementRef?.uniformMatrix4fv(boundingMatWorldUniform, false, matWorld);
        renderRef.elementRef?.uniformMatrix4fv(boundingMatViewProjUniform, false, matViewProj);
        /* Issue draw call */
        try {
            renderRef.elementRef?.drawElements(renderRef.elementRef.LINE_LOOP, this._boundingIndices.length, renderRef.elementRef.UNSIGNED_SHORT, 0);
        }
        catch (e) {
            throw new Error(e);
        }
    }
    /* COLLISION DETECTION */
    isCollidingBBox(playerObject) {
        // ASSUME FOR NOW THAT WE ARE INTERACTING WITH SPHERES
        const playerLocation = playerObject.playerObject.position;
        const playerRadius = playerObject.playerObject._radius;
        const playerVelocity = playerObject.velocity;
        /**
         * REPLACE WITH SWEPT SPHERE ALGO AS POSSIBILITY OF TUNNELING
         */
        const playerProjectedLocation = vec3.create();
        vec3.add(playerProjectedLocation, playerLocation, playerVelocity);
        const sqrDist = vec3.squaredDistance(playerProjectedLocation, this.position);
        /* Arbitrary radius divisor */
        const radiusSum = playerRadius + this._radius;
        return sqrDist <= radiusSum * radiusSum;
    }
    _generateBoundingBox() {
        /* Model tranform */
        const matWorld = mat4.create();
        const rotationMatrix = mat4.create();
        quat.normalize(this._rotationQuat, this._rotationQuat);
        mat4.fromQuat(rotationMatrix, this._rotationQuat);
        // Apply translation to the world matrix
        mat4.translate(matWorld, matWorld, this.position);
        mat4.scale(matWorld, matWorld, vec3.fromValues(this._radius, this._radius, this._radius));
        mat4.multiply(matWorld, matWorld, rotationMatrix);
        // Define cube vertices in local space
        const radius = this._radius;
        // Apply the transformation to the center of the sphere
        const transformedCenter = vec3.create();
        vec3.transformMat4(transformedCenter, this.position, matWorld);
        // Calculate the transformed radius (if scaled)
        const scaleFactor = Math.max(matWorld[0], matWorld[5], matWorld[10]); // Get scaling factors from matWorld
        const transformedRadius = radius * scaleFactor;
        let i = 0;
        let j = 0;
        const verticesToTransform = [];
        let vertexBuffer = [];
        while (i < this._vertexArray.length) {
            vertexBuffer.push(this._vertexArray[i]);
            j += 1;
            if (j > 2) {
                verticesToTransform.push(vertexBuffer);
                vertexBuffer = [];
                j = 0;
            }
            i += 1;
        }
        const bboxVertices = [];
        verticesToTransform.forEach((vertex) => {
            const transformedVertex = vec3.create();
            vec3.transformMat4(transformedVertex, vertex, matWorld);
            bboxVertices.push(transformedVertex[0], transformedVertex[1], transformedVertex[2]);
        });
        this._boundingVertices = new Float32Array(bboxVertices);
        this._boundingIndices = new Uint16Array(this._vertexIndices);
        // The bounding sphere is defined by the transformed center and transformed radius
        this.boundingBox = {
            transformedCenter,
            transformedRadius,
        };
    }
    _updateBoundingBox() {
        /* Model tranform */
        const matWorld = mat4.create();
        const rotationMatrix = mat4.create();
        quat.normalize(this._rotationQuat, this._rotationQuat);
        mat4.fromQuat(rotationMatrix, this._rotationQuat);
        // Apply translation to the world matrix
        mat4.translate(matWorld, matWorld, this.position);
        mat4.scale(matWorld, matWorld, vec3.fromValues(this._radius, this._radius, this._radius));
        mat4.multiply(matWorld, matWorld, rotationMatrix);
        // Define cube vertices in local space
        const radius = this._radius;
        // Apply the transformation to the center of the sphere
        const transformedCenter = vec3.create();
        vec3.transformMat4(transformedCenter, this.position, matWorld);
        // Calculate the transformed radius (if scaled)
        const scaleFactor = Math.max(matWorld[0], matWorld[5], matWorld[10]); // Get scaling factors from matWorld
        const transformedRadius = radius * (scaleFactor);
        // The bounding sphere is defined by the transformed center and transformed radius
        this.boundingBox = {
            transformedCenter,
            transformedRadius,
        };
    }
}
export default SpherePrimitive;
