import { mat4, vec3 } from "gl-matrix";
/**
 * Base class used for levels.
 * @class
 */
class FreeCamera {
    /**
     * Camera view individual vectors
     */
    cameraMatrix = null;
    targetVector = null;
    positionVector = null;
    cameraRotation = null;
    frontVector = null;
    rightVector = null;
    upVector = null;
    globalYaw = null;
    localPitch = null;
    /**
     * Initialises values specific to a class, including scene, camera, rotation,
     * min map, draw and update functions etc
     */
    constructor(position) {
        this.cameraMatrix = mat4.create();
        this.positionVector = vec3.fromValues(position[0], position[1], position[2]);
        this.cameraRotation = mat4.create();
        this.targetVector = vec3.create();
        this.globalYaw = 0;
        this.localPitch = 0;
        this.upVector = vec3.fromValues(0, 1, 0);
        this.frontVector = vec3.fromValues(0, 0, -1);
    }
    /**
     * Updates all values on objects and sub-objects in scene with
     * global values and calls re draws on all elements associated with the scene.
     * @return void
     */
    update(inputState) {
        let aV = 0; // Pitch
        if (inputState.isWPressed)
            aV = 0.05;
        if (inputState.isSPressed)
            aV = -0.05;
        let aH = 0; // Yaw
        if (inputState.isDPressed)
            aH = -0.05;
        if (inputState.isAPressed)
            aH = 0.05;
        /* UPDATE CAMERA POSITION */
        let dp = 0;
        if (inputState.isUpArrowPressed)
            dp = -0.3;
        if (inputState.isDownArrowPressed)
            dp = 0.3;
        let ds = 0;
        if (inputState.isRightArrowPressed)
            ds = 0.3;
        if (inputState.isLeftArrowPressed)
            ds = -0.3;
        this.globalYaw += aH;
        this.localPitch += aV;
        // Clamp the pitch to the range [-89°, 89°] in radians
        if (this.localPitch > 30 * (Math.PI / 180)) {
            this.localPitch = 30 * (Math.PI / 180);
            aV = 0;
        }
        else if (this.localPitch < -30 * (Math.PI / 180)) {
            this.localPitch = -30 * (Math.PI / 180);
            aV = 0;
        }
        // Translate camera position and target vecotr
        const dx = (dp * Math.sin(this.globalYaw)) + (ds * Math.cos(-this.globalYaw));
        const dz = (dp * Math.cos(this.globalYaw)) + (ds * Math.sin(-this.globalYaw));
        const dy = dp * Math.sin(-this.localPitch);
        vec3.add(this.positionVector, this.positionVector, vec3.fromValues(dx, dy, dz));
        // Apply pitch (rotation around the X-axis) - up/down
        // mat4.rotateX(this.cameraRotation, this.cameraRotation, aV); // aV controls pitch
        mat4.rotateX(this.cameraRotation, this.cameraRotation, aV); // aV controls pitch
        // Create a forward vector and apply the camera's rotation to it
        const forward = vec3.fromValues(0, 0, -1); // Initially, the camera looks down the negative Z-axis
        vec3.transformMat4(forward, forward, this.cameraRotation); // Apply rotation to the forward vector
        // Update the target position based on the camera's position and its forward direction
        vec3.add(this.targetVector, this.positionVector, forward);
        const finalVector = vec3.fromValues(0, 1, 0);
        vec3.rotateY(finalVector, this.targetVector, this.positionVector, this.globalYaw);
        mat4.lookAt(this.cameraMatrix, this.positionVector, finalVector, this.upVector);
    }
}
export default FreeCamera;
