import { vec3 } from "gl-matrix";
import CollisionHandler from "@utils/collisionHelper";
/**
 * Base class used for levels.
 * @class
 */
class LevelAbstract {
    /**
     *  CAMERA
     */
    sceneObjectArray = [];
    projectionMatrix = null;
    camera = null;
    player = null;
    enableFreeCam = false;
    /**
     * PHYSICS  INTERACTIONS
     */
    collisionHandler = null;
    /**
     * WORLD CONSTANTS
     */
    gravity = vec3.fromValues(0, 0, 0);
    /**
     * Initialises values specific to a class, including scene, free camera, rotation,
     * min map, draw and update functions etc
     */
    constructor(sceneObjectArray, playerObject, camera, enableFreeCam = false, gravityVec = null) {
        this.sceneObjectArray = sceneObjectArray;
        this.player = playerObject;
        // Free camera
        this.camera = camera;
        this.enableFreeCam = enableFreeCam;
        // Collision handling
        this.collisionHandler = new CollisionHandler();
        // Add world constants
        if (gravityVec)
            this.gravity = gravityVec;
    }
    /**
     * 1) Complete collision detection and resolve collisions here
     *
     * Updates all values on objects and sub-objects in scene with
     * global values and calls re draws on all elements associated with the scene.
     *
     * @return void
     */
    update(inputState) {
        // If no camera available then throw error
        if (!this.enableFreeCam && !this.player) {
            throw new Error("Camera required");
        }
        if (this.enableFreeCam && !this.camera) {
            throw new Error("Free camera required");
        }
        // Update camera state
        if (this.enableFreeCam)
            this.camera.update(inputState);
        let isColliding = false;
        this.player?.updateMovement(inputState, this.gravity);
        // COLLISION DETECTION
        for (let object of this.sceneObjectArray) {
            // If collision detected, then collision resolution handled by collision controller
            if (!isColliding) {
                isColliding = object.isCollidingBBox(this.player, this.collisionHandler);
            }
        }
        // Collision resolution
        if (isColliding) {
            this.player?.rePosition(vec3.scale(vec3.create(), this.player.velocity, -1));
            this.player.velocity = this.collisionHandler?.sphereOnStatCubeE(this.collisionHandler.collisionNormal, this.player?.velocity);
        }
        // Update player position and camera states
        if (!this.enableFreeCam && this.player)
            this.player.updatePosition(isColliding);
        // Draw all objects in scene
        for (let object of this.sceneObjectArray) {
            object.draw(this.projectionMatrix, this.enableFreeCam ? this.camera.cameraMatrix : this.player.cameraMatrix);
        }
        // Draw player object
        if (this.player) {
            this.player.playerObject?.draw(this.projectionMatrix, this.enableFreeCam ? this.camera.cameraMatrix : this.player.cameraMatrix);
        }
    }
}
export default LevelAbstract;
