import { mat4, vec3 } from "gl-matrix";
// Transform normals with scale and rotation matrix
const computeTransformedNormals = (normalsArray, rotationMatrix) => {
    // Rotate the normals by the transformation matrix
    return normalsArray.map(normal => vec3.transformMat4(normal, normal, rotationMatrix));
};
// Function to create a combined rotation matrix from three angles (X, Y, Z)
const createRotationMatrix = (rotationVector) => {
    // Create individual rotation matrices
    const rotationX = mat4.create();
    const rotationY = mat4.create();
    const rotationZ = mat4.create();
    // Apply rotations for X, Y, Z axes
    mat4.rotateX(rotationX, rotationX, rotationVector[0]); // Rotate around X by angleX
    mat4.rotateY(rotationY, rotationY, rotationVector[1]); // Rotate around Y by angleY
    mat4.rotateZ(rotationZ, rotationZ, rotationVector[2]); // Rotate around Z by angleZ
    // Combine the rotations (apply Z -> Y -> X)
    const combinedRotation = mat4.create();
    mat4.multiply(combinedRotation, rotationZ, rotationY);
    mat4.multiply(combinedRotation, combinedRotation, rotationX);
    return combinedRotation;
};
/* Project array of vertices onto a given normal. Used for SAT */
const projectVerticesOntoNormal = (vertexArray, normalAxis) => {
    // Start with first value
    let min = vec3.dot(vertexArray[0], normalAxis);
    let max = min;
    for (let i = 0; i < vertexArray.length; i++) {
        let projection = vec3.dot(vertexArray[i], normalAxis);
        min = Math.min(min, projection);
        max = Math.max(max, projection);
    }
    return {
        min,
        max
    };
};
/**
 * Compute the cross product between a cube's edge vector and the vector from the sphere's center to the edge's vertex.
 * This will generate a separating axis that we can use in the Separating Axis Theorem (SAT) collision detection.
 *
 * @param {Array} cubeVertices - An array of the cube's vertices (8 vertices for a cube).
 * @param {vec3} spherePosition - The position of the sphere (the center of the sphere).
 * @returns {vec3} - The separating axis derived from the cross product.
 */
export function computeCrossProductEdge(cubeVertices, spherePosition) {
    const axes = []; // Array to hold cross product axes
    // Loop over the cube's edges (defined by pairs of vertices)
    const edgePairs = [
        [0, 1], [1, 2], [2, 3], [3, 0], // Front face edges
        [4, 5], [5, 6], [6, 7], [7, 4], // Back face edges
        [0, 4], [1, 5], [2, 6], [3, 7] // Vertical edges connecting front and back faces
    ];
    edgePairs.forEach(pair => {
        // Get the two vertices that define the edge
        const v1 = cubeVertices[pair[0]]; // First vertex
        const v2 = cubeVertices[pair[1]]; // Second vertex
        // Compute the edge vector (v2 - v1)
        const edgeVector = vec3.create();
        vec3.subtract(edgeVector, v2, v1);
        // Compute the vector from the sphere's center to one of the edge's vertices (e.g., v1)
        const centerToEdgeVector = vec3.create();
        vec3.subtract(centerToEdgeVector, v1, spherePosition);
        // Compute the cross product between the edge vector and the center-to-edge vector
        const crossProduct = vec3.create();
        vec3.cross(crossProduct, edgeVector, centerToEdgeVector);
        // Add this cross product as an axis (separating axis)
        axes.push(crossProduct);
    });
    // In SAT, we need to test for separation along each of the axes
    return axes;
}
