/**
 * Entry point to implementing level object
 */
import LevelAbstract from "@game/levels/levelAbstract";
import CubePrimitive from "@models/cube/cube";
import SpherePrimitive from "@models/sphere/sphere";
import FreeCamera from "@cameras/FreeCamera";
import PlayerObject from "@models/player/PlayerObject";
import { vec3 } from "gl-matrix";
let levelTwo = null;
try {
    const plane = new CubePrimitive(null, null, vec3.fromValues(0, 0, 0), vec3.fromValues(10, 400, 400), vec3.fromValues(0, 0, Math.PI / 2), true);
    const playerSphere = new SpherePrimitive(`#version 300 es
  precision mediump float;
  
  in vec3 a_position;
  uniform mat4 matWorld;
  uniform mat4 matViewProj;
  out vec4 fragmentColor;
  void main() {
    fragmentColor =  matViewProj * matWorld * vec4(a_position, 1.0);
    gl_Position = matViewProj * matWorld * vec4(a_position, 1.0);
  }`, `#version 300 es
  precision mediump float;

  in vec4 fragmentColor;
  out vec4 fragColor;

  // Plot a line on Y using a value between 0.0-1.0
  void main(){
    fragColor = fragmentColor;
  }
  
  `, 50, 500, 50, 0.5, 0, 0, 0);
    // Create camera
    const freeCamera = new FreeCamera([0, 0, 0]);
    // Create character object
    const playerObject = new PlayerObject(playerSphere, [0, 10, 20], 25);
    // Ambient  gravity
    const gravity = vec3.fromValues(0, -0.02, 0);
    const cubeArray = [];
    // Generate random shapes
    for (let i = 0; i < 100; i++) {
        const cube = new CubePrimitive(null, null, vec3.fromValues(Math.random() * 400, Math.random() * 400, Math.random() * 400), vec3.fromValues(Math.random() * 50, Math.random() * 50, Math.random() * 50), vec3.fromValues(0, 0, 0), true);
        cubeArray.push(cube);
    }
    levelTwo = new LevelAbstract([
        plane,
        ...cubeArray
    ], playerObject, freeCamera, false, gravity);
}
catch (e) {
    console.log(e);
    console.trace();
    throw new Error(e);
}
export default levelTwo;
